import{_ as a,o as i,c as l,a2 as e}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"关于我","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1794790394000}'),d={name:"about.md"};function s(r,t,o,n,c,u){return i(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to &quot;关于我&quot;">​</a></h1><blockquote><p>一句话介绍：四川传媒学院计算机科学与技术专业大一在读，方向前端 / Web 开发， 正在寻找第一份前端开发实习。</p></blockquote><h2 id="我是谁" tabindex="-1">我是谁 <a class="header-anchor" href="#我是谁" aria-label="Permalink to &quot;我是谁&quot;">​</a></h2><p>我是 <strong>柴杰</strong>，2026 年 9 月入学四川传媒学院，读计算机科学与技术，现在大一。</p><p>我选前端的原因很直接：我喜欢&quot;写完就能看到&quot;的东西。写一段代码，刷新一下浏览器， 页面就变了 —— 这种反馈让我愿意反复练。现在我还在打基础，HTML 和 CSS 能写静态页面， JavaScript 在学，接下来准备系统学 Vue 3。</p><p>我清楚自己现在最缺的是<strong>真实项目经验</strong>，所以这个网站的意义不是包装自己， 而是把学习进度、做过的东西、踩过的坑如实记下来。每做完一个项目，我就补一篇详情页。</p><h2 id="我在找什么" tabindex="-1">我在找什么 <a class="header-anchor" href="#我在找什么" aria-label="Permalink to &quot;我在找什么&quot;">​</a></h2><ul><li><strong>岗位</strong>：前端开发实习生（Web 前端、页面开发、小程序方向都可以）</li><li><strong>地点</strong>：成都，或远程</li><li><strong>时间</strong>：寒暑假可全职；学期内每周 2–3 天</li><li><strong>希望团队</strong>：有人愿意带、能让我接触真实项目，哪怕从改样式、修小 bug 开始</li><li><strong>我的诉求</strong>：把课堂上的东西用到真实业务里，学会怎么做能上线的代码</li></ul><h2 id="技能与学习进度" tabindex="-1">技能与学习进度 <a class="header-anchor" href="#技能与学习进度" aria-label="Permalink to &quot;技能与学习进度&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">这张表请按你的真实情况改</p><p>不会的、没学过的直接删掉 —— 大一写&quot;熟练&quot;反而扣分。诚实写&quot;在学&quot;更容易被接受。</p></div><table tabindex="0"><thead><tr><th>类别</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td>基础</td><td>HTML / CSS，能写静态页面与 Flex 布局</td><td>在学</td></tr><tr><td>语言</td><td>JavaScript（语法、DOM 操作）</td><td>在学</td></tr><tr><td>框架</td><td>Vue 3（组件、路由）</td><td>计划中</td></tr><tr><td>工具</td><td>Git / GitHub，会用命令行提交与部署</td><td>在学</td></tr><tr><td>工具</td><td>VS Code、浏览器开发者工具</td><td>常用</td></tr><tr><td>课程</td><td>C 语言程序设计、计算机导论</td><td>课程学习中</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><div class="timeline"><div class="item"><div class="item-head"><span>入学：计算机科学与技术</span><span class="item-time">2026.09</span></div><div class="item-org">四川传媒学院</div><ul><li>开始系统学计算机基础：C 语言、计算机导论。</li><li>确定方向：前端 / Web 开发。</li></ul></div><div class="item"><div class="item-head"><span>打基础：HTML / CSS / JavaScript</span><span class="item-time">2026.10 – 至今</span></div><div class="item-org">自学 + 课程练习</div><ul><li>能手写静态页面，理解盒模型、Flex 布局与常见排版。</li><li>正在学 JavaScript 语法与 DOM 操作，边学边做小练习。</li><li>同时练 Git：提交、分支、把站点部署到 GitHub Pages。</li></ul></div><div class="item"><div class="item-head"><span>下一步：Vue 3 + 第一个完整项目</span><span class="item-time">计划中</span></div><div class="item-org">目标：2027 年暑假前投出第一份实习</div><ul><li>学完 Vue 3 组件化开发，能独立做一个带数据的页面。</li><li>完成第一个完整项目，并按模板写成项目详情页。</li></ul></div></div><h2 id="教育背景" tabindex="-1">教育背景 <a class="header-anchor" href="#教育背景" aria-label="Permalink to &quot;教育背景&quot;">​</a></h2><ul><li><strong>四川传媒学院</strong> · 计算机科学与技术 · 本科 · 2026.09 – 2030.06（大一在读）</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><ul><li>英语：待补充（例如四级 / 六级成绩，能否读英文技术文档）</li><li>兴趣：待补充</li><li>其他值得一提的经历：待补充（社团、竞赛、志愿活动等）</li></ul><div class="tip custom-block"><p class="custom-block-title">这一节可以删</p><p>如果没有什么可写的，直接把这一节删掉 —— 留一堆&quot;待补充&quot;不如不写。</p></div><h2 id="想进一步了解" tabindex="-1">想进一步了解 <a class="header-anchor" href="#想进一步了解" aria-label="Permalink to &quot;想进一步了解&quot;">​</a></h2><ul><li>📄 <a href="/resume">学生版简历</a> —— 结构化、可打印</li><li>🧩 <a href="/projects/">项目作品</a> —— 目前主要是进行中的计划与进度</li><li>✉️ <a href="/contact">联系我</a> —— 24 小时内回复</li></ul>',20)])])}const m=a(d,[["render",s]]);export{p as __pageData,m as default};
